#!/usr/bin/env python3
"""Builds shop.sqlite for the eval: orders(id, order_date, status, archived)."""
import sqlite3, os
path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "shop.sqlite")
if os.path.exists(path):
    os.remove(path)
c = sqlite3.connect(path)
c.execute("CREATE TABLE orders (id INTEGER PRIMARY KEY, order_date TEXT NOT NULL, status TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0)")
rows = []
n = 1
for m in range(1, 13):
    for d in range(1, 11):
        rows.append((n, "2023-%02d-%02d" % (m, d), "fulfilled", 0)); n += 1
for y in (2024, 2025):
    for m in range(1, 10):
        for d in range(1, 11):
            rows.append((n, "%d-%02d-%02d" % (y, m, d), "fulfilled" if d % 7 else "refunded", 0)); n += 1
c.executemany("INSERT INTO orders VALUES (?,?,?,?)", rows)
c.commit()
print("shop.sqlite: %d orders" % len(rows))
